%[metadata:view]
%   data: {"layout":"inline","rightPanelPercent":40}
%---
%[control:slider:8b9c]
%   data: {"defaultValue":2.424E+8,"label":"学号（课堂演示使用末两位）","max":2.42400099E+8,"min":2.424E+8,"run":"Nothing","runOn":"ValueChanged","step":1}
%---
%[control:slider:360e]
%   data: {"defaultValue":0.5,"label":"荷电状态","max":0.8,"min":0.2,"run":"Section","runOn":"ValueChanged","step":0.05}
%---
%[control:slider:713c]
%   data: {"defaultValue":1,"label":"配置选择变量 w","max":1,"min":0,"run":"Section","runOn":"ValueChanged","step":1}
%---
%[control:slider:0b9c]
%   data: {"defaultValue":0.96,"label":"线性模型电压下限 \/ p.u.","max":0.975,"min":0.95,"run":"Nothing","runOn":"ValueChanged","step":0.001}
%---
%[control:slider:440a]
%   data: {"defaultValue":1,"label":"单位能量投资费用倍率","max":2,"min":0.5,"run":"Nothing","runOn":"ValueChanged","step":0.1}
%---
